('advanced-native-1111', '["phrase"]'::jsonb, '{"advanced-native-1111-v1-audio":{"type":"mc","answers":["Separate non-urgent updates were reduced, while urgent changes were still sent immediately."],"options":["The group had already proved the summary suited each member before asking them.","Separate non-urgent updates were reduced, while urgent changes were still sent immediately.","The group stopped sending every kind of update, including urgent room changes.","The summary was added without changing the number of separate non-urgent messages."]},"advanced-native-1111-v2-reply":{"type":"mc","answers":["We wanted fewer separate messages interrupting the writing sessions.","We wanted to cut down on separate updates without delaying urgent room changes.","A summary could carry the routine news while urgent messages kept a direct route.","The change let us reduce interruptions and then ask whether the new format was easier to use."],"options":["We wanted fewer separate messages interrupting the writing sessions.","We wanted to cut down on separate updates without delaying urgent room changes.","A summary could carry the routine news while urgent messages kept a direct route.","The change let us reduce interruptions and then ask whether the new format was easier to use."]},"advanced-native-1111-v1-scene":{"type":"mc","answers":["She has cut down on draft paper while keeping enough for the large drawings."],"options":["Her paper use increased from four sheets to six after the change.","She has cut down on draft paper while keeping enough for the large drawings.","She has stopped using paper for any drawing or draft."]},"advanced-native-1111-v1-contrast":{"type":"mc","answers":["It has necessarily been eliminated completely."],"options":["Its amount or frequency is reduced.","It has necessarily been eliminated completely.","The context should explain what is being reduced."]},"advanced-native-1111-v1-branch":{"type":"mc","answers":["We are cutting down on routine messages